"""داده‌های مشترک دو پوسته فروشگاه سنگ مصنوعی عصرجدید"""

FA_DIGITS = "۰۱۲۳۴۵۶۷۸۹"


def fa_num(value, decimals=0):
    """تبدیل عدد به رقم فارسی با جداکننده هزارگان"""
    if isinstance(value, str):
        return value
    if decimals:
        txt = f"{value:,.{decimals}f}"
    else:
        txt = f"{value:,.0f}"
    return "".join(FA_DIGITS[int(ch)] if ch.isdigit() else ch for ch in txt)


def money(value, suffix="تومان"):
    return f"{fa_num(value)} {suffix}"


